"use client";

import * as React from "react";
import { Tabs as TabsPrimitive } from "@base-ui/react/tabs";
import { motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";
import { focusRing, panelSpring, selectedOption, optionTrack } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** What a trigger needs from its Tabs to draw the sliding panel. */
interface TabsState {
  panelId: string;
  reduceMotion: boolean;
}

const TabsContext = React.createContext<TabsState | null>(null);

/** Mallow Tabs: a segmented control whose violet-ringed tint slides to the active tab on a critically damped spring. */
const Tabs = React.forwardRef<HTMLDivElement, WithClassName<TabsPrimitive.Root.Props>>((props, ref) => {
  const panelId = React.useId();
  const reduceMotion = useReducedMotion() ?? false;

  return (
    <TabsContext.Provider value={{ panelId, reduceMotion }}>
      <TabsPrimitive.Root ref={ref} data-slot="tabs" {...props} />
    </TabsContext.Provider>
  );
});
Tabs.displayName = "Tabs";

/** The row of tabs, held in a lilac option track. */
const TabsList = React.forwardRef<HTMLDivElement, WithClassName<TabsPrimitive.List.Props>>(
  ({ className, ...props }, ref) => (
    <TabsPrimitive.List
      ref={ref}
      data-slot="tabs-list"
      className={cn(
        "isolate inline-flex h-11 items-center justify-center gap-1 rounded-xl p-1 text-muted-foreground",
        optionTrack,
        className,
      )}
      {...props}
    />
  ),
);
TabsList.displayName = "TabsList";

/** One tab in muted text that turns to full ink while the chosen-option tint rests under it. */
const TabsTrigger = React.forwardRef<HTMLButtonElement, WithClassName<TabsPrimitive.Tab.Props>>(
  ({ className, children, ...props }, ref) => {
    const tabs = React.useContext(TabsContext);

    return (
      <TabsPrimitive.Tab
        ref={ref}
        data-slot="tabs-trigger"
        className={cn(
          "relative inline-flex h-full items-center justify-center whitespace-nowrap rounded-lg px-4 text-sm font-medium",
          "text-muted-foreground transition-colors duration-fast ease-(--ease-out) hover:text-foreground",
          "data-[active]:text-foreground",
          // Outside a Mallow Tabs there is no panel to slide, so the trigger takes the tint itself.
          !tabs && "data-[active]:bg-(--option-face) data-[active]:shadow-(--option-edge)",
          focusRing,
          "disabled:pointer-events-none disabled:opacity-50",
          "data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
          className,
        )}
        {...props}
        render={(tabProps, state) => (
          <button {...tabProps}>
            {tabs && state.active && (
              <motion.span
                layoutId={`${tabs.panelId}-panel`}
                aria-hidden="true"
                data-slot="tabs-panel"
                className={cn(selectedOption, "absolute inset-0 z-0 rounded-lg")}
                transition={tabs.reduceMotion ? { duration: 0 } : panelSpring}
              />
            )}
            <span className="relative z-10 inline-flex items-center gap-2 [&_svg]:size-4 [&_svg]:shrink-0">
              {children}
            </span>
          </button>
        )}
      />
    );
  },
);
TabsTrigger.displayName = "TabsTrigger";

/** The active panel, set below the tab row. */
const TabsContent = React.forwardRef<HTMLDivElement, WithClassName<TabsPrimitive.Panel.Props>>(
  ({ className, ...props }, ref) => (
    <TabsPrimitive.Panel
      ref={ref}
      data-slot="tabs-content"
      className={cn("mt-4 rounded-lg", focusRing, className)}
      {...props}
    />
  ),
);
TabsContent.displayName = "TabsContent";

export { Tabs, TabsList, TabsTrigger, TabsContent };
